class Solution {
    public int findMaximumXOR(int[] nums){
        int answer=0,mask=0;
        for(int bit=30;bit>=0;bit--){
            mask|=1<<bit;
            Set<Integer> prefixes=new HashSet<>();
            for(int value:nums)prefixes.add(value&mask);
            int candidate=answer|1<<bit;
            for(int prefix:prefixes)if(prefixes.contains(prefix^candidate)){
                answer=candidate;
                break;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findMaximumXOR(nums:IntArray):Int{
        var answer=0;
        var mask=0;
        for(bit in 30 downTo 0){
            mask=mask or (1 shl bit);
            val prefixes=nums.mapTo(hashSetOf()){
                it and mask
            };
            val candidate=answer or (1 shl bit);
            if(prefixes.any{
                (it xor candidate) in prefixes
            })answer=candidate
        };
        return answer
    }
}

